// ELEMENTS:
// 1. Três faixas verticais (src, src2, src3) com gutters navy finos
// 2. Cada faixa revela-se de baixo para cima, escalonada, e deriva devagar
// 3. Gradiente navy no rodapé com barra azul IAD + legenda em serifa branca (anim.text)
// 4. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#0E1626";
const CYAN = "#05B8E6";
const CORAL = "#F06052";
const WHITE = "#F4F1EA";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.22) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const Triptico: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const land = format === "landscape";
  const u = land ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const first = String(p.src ?? "");
  const srcs = [first, String(p.src2 ?? first), String(p.src3 ?? p.src2 ?? first)];
  const caption = String(anim.text ?? "").trim();

  const t = (delay: number, len = 0.8): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const drift = interpolate(f, [0, T], [0, 1], { ...clamp, easing: Easing.inOut(Easing.sin) });

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", overflow: "hidden", backgroundColor: NAVY }}>
      <div style={{ position: "absolute", inset: 0, display: "flex", gap: 12 * u }}>
        {srcs.map((src, i) => {
          const r = t(i * 0.2);
          return (
            <div key={i} style={{ flex: 1, minWidth: 0, overflow: "hidden", clipPath: `inset(${(1 - r) * 100}% 0 0 0)` }}>
              {src ? (
                <Img
                  src={src}
                  style={{
                    width: "100%",
                    height: "100%",
                    objectFit: "cover",
                    filter: "saturate(0.88) contrast(1.05)",
                    transform: `scale(1.1) translateY(${(i % 2 ? -1 : 1) * (2 - 4 * drift)}%)`,
                  }}
                />
              ) : null}
            </div>
          );
        })}
      </div>
      {caption ? (
        <>
          <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(14,22,38,0) 55%, rgba(14,22,38,0.9) 100%)" }} />
          <div
            style={{
              position: "absolute",
              left: 72 * u,
              right: 72 * u,
              bottom: (land ? 72 : 184) * u,
              display: "flex",
              flexDirection: "column",
              gap: 28 * u,
              opacity: t(0.7),
            }}
          >
            <div style={{ width: interpolate(t(0.6), [0, 1], [0, 96 * u]), height: 4 * u, background: CYAN }} />
            <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 500, fontSize: 96 * u, lineHeight: 1.04, color: WHITE }}>{caption}</div>
          </div>
        </>
      ) : null}
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default Triptico;
